contains(profile_backup_sync, 'client:putDeluxeProfile(server.username, server.userkey, payload', "protected config backup must use the dedicated Deluxe profile endpoint")
contains(profile_backup_sync, 'access = captured.access', "protected server authentication must accompany only the dedicated profile upload")
