excludes(main, 'payload.deluxe_profile = {', "KOReader settings snapshots must never piggyback Deluxe-Sync credentials")
excludes(main, 'stored_state.deluxe_profile_checksum ==', "KOReader settings dedupe must not depend on protected-profile changes")

contains(main, 'function ProgressSyncDeluxe:checkDeluxeProfileCandidateForServer(server, client, callback)', "cross-device candidate compatibility delegate missing")
contains(main, 'self.restore_migration_controller:checkDeluxeProfileCandidateForServer(server, client, callback)', "candidate discovery must delegate to the restore controller")
