contains(restore, 'client:requestDeluxeProfileRestore(server.username, server.userkey', "reader must target the selected profile to itself")
contains(main, 'function ProgressSyncDeluxe:applyCurrentDeluxeProfileRestore(server, client, registration, expected_profile_id, callback)', "candidate Restore compatibility delegate missing")
contains(restore, 'self:applyCurrentDeluxeProfileRestore(server, client, registration, profile_id', "candidate Restore must proceed directly to validated application")
