contains(main, 'function ProgressSyncDeluxe:checkDeluxeProfileRestoreForServer(server, client, callback)', "pending Deluxe restore compatibility delegate missing")
contains(main, 'self.restore_migration_controller:checkDeluxeProfileRestoreForServer(server, client, callback)', "pending restore polling must delegate to the restore controller")
contains(restore, 'client:getCurrentDeluxeProfileRestore(server.username, server.userkey', "pending Deluxe restore must use authenticated transport")
contains(main, 'function ProgressSyncDeluxe:showDeluxeProfileRestorePrompt(server, restore, client, registration)', "Deluxe restore confirmation compatibility delegate missing")
contains(restore, 'text = _("Reject Restore Request")', "only a genuinely pending restore request should expose explicit rejection")
contains(restore, 'No new accounts are created.', "restore prompt must explain account identity preservation")
contains(restore, 'DeluxeProfileAdapter.apply(owner.store, {', "confirmed pending profile must be applied through the safe adapter")
contains(restore, 'client:completeDeluxeProfileRestore(server.username, server.userkey', "reader restore decision must be acknowledged")
contains(restore, 'This Deluxe-Sync restore request is no longer pending. No server setup was changed.', "stale restore prompt must fail closed")
