contains(main, 'deluxe_profiles = true', "device registration must advertise Deluxe profile support")
contains(main, 'deluxe_profile_restore = true', "device registration must advertise Deluxe profile restore support")
contains(settings_sync, 'owner:checkDeluxeProfileMigrationForServer(server, client)', "normal Stage 9 lifecycle must check profile restore/candidates")
contains(main, 'function ProgressSyncDeluxe:refreshEnhancedCapabilitiesForAll()', "network capability refresh must remain the migration trigger")

local candidate_function = assert(restore:find('function RestoreMigrationController:showDeluxeProfileCandidatePrompt(server, candidate, client, registration)', 1, true))
local candidate_end = assert(restore:find('\nend\n\nfunction RestoreMigrationController:checkDeluxeProfileCandidateForServer', candidate_function, true))
local candidate_body = restore:sub(candidate_function, candidate_end)
local candidate_prompt = assert(candidate_body:find('title = _("Deluxe-Sync backup found on another reader")', 1, true))
local candidate_restore = assert(candidate_body:find('text = _("Restore")', candidate_prompt, true))
local request_restore = assert(candidate_body:find('client:requestDeluxeProfileRestore(server.username, server.userkey', candidate_restore, true))
local apply_restore = assert(candidate_body:find('self:applyCurrentDeluxeProfileRestore(server, client, registration, profile_id', request_restore, true))
assert(not candidate_body:find('Reject Restore Request', 1, true), "discovered backup candidates must not expose pending-request rejection")
assert(request_restore > candidate_restore, "restore request must only be created after explicit candidate confirmation")
assert(apply_restore > request_restore, "candidate Restore must immediately revalidate and apply the created request")

local restore_prompt = assert(restore:find('title = _("Restore Deluxe-Sync server setup?")', 1, true))
local restore_button = assert(restore:find('text = _("Restore")', restore_prompt, true))
local revalidate = assert(restore:find('client:getCurrentDeluxeProfileRestore(server.username, server.userkey', restore_button, true))
local apply_profile = assert(restore:find('DeluxeProfileAdapter.apply(owner.store, {', revalidate, true))
assert(revalidate > restore_button, "pending Deluxe profile must be revalidated after explicit restore confirmation")
assert(apply_profile > revalidate, "Deluxe profile must not be applied before pending-request revalidation")

print("deluxe_profile_sync_test.lua: OK")
